import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.shared .align 16 .b32 sA[512];    // 16 x 32 tile of A
.shared .align 16 .b32 sB[512];    // 32 x 16 tile of B
.visible .entry ut_triu_matmul_f32(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N_param
)
{
    .reg .pred %p_i_in, %p_j_in, %p_valid, %p_upper, %p_kdone, %pA0_i, %pA0_k, %pA0, %pA1_i, %pA1_k, %pA1, %pB0_k, %pB0_j, %pB0, %pB1_k, %pB1_j, %pB1, %p_compute, %p_lt0, %p_gt0, %p_gt1, %p_empty, %p_tdone;
    .reg .b32 %rBx, %rBy, %rTx, %rTy, %rBDx, %rBDy, %rBlockCol, %rj, %rBlockRow, %ri, %rN, %rZero, %rKTILE, %rMTILE, %rNTILE, %rNm1, %rTidLin, %rKB, %rIdxA0, %rRowA0, %rColA0, %rIGlobA0, %rKGlobA0, %rAO0, %rIdxA1, %rRowA1, %rColA1, %rIGlobA1, %rKGlobA1, %rAO1, %rIdxB0, %rRowB0, %rColB0, %rKGlobB0, %rJGlobB0, %rBO0, %rIdxB1, %rRowB1, %rColB1, %rKGlobB1, %rJGlobB1, %rBO1, %rStart, %rEnd, %rKBEnd, %rLocalStart, %rLocalEnd, %rT, %rOffAIdx, %rOffBIdx, %rCbase, %rCidx;
    .reg .b64 %rdA, %rdB, %rdC, %rd_sA, %rd_sB, %rdAO0, %rdAPtr0, %rdSA0, %rdSAPtr0, %rdAO1, %rdAPtr1, %rdSA1, %rdSAPtr1, %rdBO0, %rdBPtr0, %rdSB0, %rdSBPtr0, %rdBO1, %rdBPtr1, %rdSB1, %rdSBPtr1, %rdOffA, %rdPtrA, %rdOffB, %rdPtrB, %rdCoff, %rdCptr;
    .reg .f32 %fAcc, %fA0, %fA1, %fB0, %fB1, %fAt, %fBt, %fOut;
    // Load parameters
    ld.param.u64 %rdA, [A_ptr];
    ld.param.u64 %rdB, [B_ptr];
    ld.param.u64 %rdC, [C_ptr];
    ld.param.u32 %rN,  [N_param];
    // Thread/block indices and dimensions
    mov.u32 %rBx, %ctaid.x;
    mov.u32 %rBy, %ctaid.y;
    mov.u32 %rTx, %tid.x;
    mov.u32 %rTy, %tid.y;
    mov.u32 %rBDx, %ntid.x;   // expect 16
    mov.u32 %rBDy, %ntid.y;   // expect 16
    // Compute global row/col for this thread (i=row, j=col)
    mul.lo.u32 %rBlockCol, %rBx, %rBDx;   // blockIdx.x * blockDim.x
    add.u32    %rj, %rBlockCol, %rTx;     // j index
    mul.lo.u32 %rBlockRow, %rBy, %rBDy;   // blockIdx.y * blockDim.y
    add.u32    %ri, %rBlockRow, %rTy;     // i index
    // Predicates
    setp.lt.u32 %p_i_in, %ri, %rN;
    setp.lt.u32 %p_j_in, %rj, %rN;
    and.pred    %p_valid, %p_i_in, %p_j_in;   // thread writes only if valid
    setp.le.u32 %p_upper, %ri, %rj;           // only upper-triangular outputs are computed
    // Prepare shared memory base pointers
    mov.u64 %rd_sA, sA;
    mov.u64 %rd_sB, sB;
    // Accumulator
    mov.f32 %fAcc, 0f00000000;
    // Precompute constants
    mov.u32 %rZero, 0;
    mov.u32 %rKTILE, 32; // K tile size
    mov.u32 %rMTILE, 16; // M tile (blockDim.y)
    mov.u32 %rNTILE, 16; // N tile (blockDim.x)
    add.u32 %rNm1, %rN, 0xffffffff; // N-1
    // Linear thread id within CTA
    mad.lo.u32 %rTidLin, %rTy, %rBDx, %rTx;  // rTy*blockDim.x + rTx
    // Outer K-loop over tiles
    mov.u32 %rKB, 0;
K_LOOP:
    setp.ge.u32 %p_kdone, %rKB, %rN;
    @%p_kdone bra K_DONE;
    // Each thread loads two A-tile elements: idx0 = t, idx1 = t + 256 (cover 512 elements)
    // ---- Load A tile (16 x 32) into shared sA ----
    // idx0
    mov.u32 %rIdxA0, %rTidLin;
    and.b32 %rRowA0, %rIdxA0, 15;        // row in [0,15]
    shr.u32 %rColA0, %rIdxA0, 4;         // col in [0,31]
    add.u32 %rIGlobA0, %rBlockRow, %rRowA0;   // i_glob
    add.u32 %rKGlobA0, %rKB, %rColA0;         // k_glob
    setp.lt.u32 %pA0_i, %rIGlobA0, %rN;
    setp.lt.u32 %pA0_k, %rKGlobA0, %rN;
    and.pred %pA0, %pA0_i, %pA0_k;
    mul.lo.u32   %rAO0, %rIGlobA0, %rN;      // i*N
    add.u32      %rAO0, %rAO0, %rKGlobA0;    // i*N + k
    mul.wide.u32 %rdAO0, %rAO0, 4;
    add.s64      %rdAPtr0, %rdA, %rdAO0;
    mov.f32 %fA0, 0f00000000;
    @%pA0 ld.global.f32 %fA0, [%rdAPtr0];
    mul.wide.u32 %rdSA0, %rIdxA0, 4;
    add.s64      %rdSAPtr0, %rd_sA, %rdSA0;
    st.shared.f32 [%rdSAPtr0], %fA0;
    // idx1
    add.u32 %rIdxA1, %rTidLin, 256;      // always < 512
    and.b32 %rRowA1, %rIdxA1, 15;
    shr.u32 %rColA1, %rIdxA1, 4;
    add.u32 %rIGlobA1, %rBlockRow, %rRowA1;
    add.u32 %rKGlobA1, %rKB, %rColA1;
    setp.lt.u32 %pA1_i, %rIGlobA1, %rN;
    setp.lt.u32 %pA1_k, %rKGlobA1, %rN;
    and.pred %pA1, %pA1_i, %pA1_k;
    mul.lo.u32   %rAO1, %rIGlobA1, %rN;
    add.u32      %rAO1, %rAO1, %rKGlobA1;
    mul.wide.u32 %rdAO1, %rAO1, 4;
    add.s64      %rdAPtr1, %rdA, %rdAO1;
    mov.f32 %fA1, 0f00000000;
    @%pA1 ld.global.f32 %fA1, [%rdAPtr1];
    mul.wide.u32 %rdSA1, %rIdxA1, 4;
    add.s64      %rdSAPtr1, %rd_sA, %rdSA1;
    st.shared.f32 [%rdSAPtr1], %fA1;
    // ---- Load B tile (32 x 16) into shared sB ----
    // idx0
    mov.u32 %rIdxB0, %rTidLin;
    and.b32 %rRowB0, %rIdxB0, 31;        // k in [0,31]
    shr.u32 %rColB0, %rIdxB0, 5;         // n in [0,15]
    add.u32 %rKGlobB0, %rKB, %rRowB0;    // k_glob
    add.u32 %rJGlobB0, %rBlockCol, %rColB0; // j_glob
    setp.lt.u32 %pB0_k, %rKGlobB0, %rN;
    setp.lt.u32 %pB0_j, %rJGlobB0, %rN;
    and.pred %pB0, %pB0_k, %pB0_j;
    mul.lo.u32   %rBO0, %rKGlobB0, %rN;   // k*N
    add.u32      %rBO0, %rBO0, %rJGlobB0; // k*N + j
    mul.wide.u32 %rdBO0, %rBO0, 4;
    add.s64      %rdBPtr0, %rdB, %rdBO0;
    mov.f32 %fB0, 0f00000000;
    @%pB0 ld.global.f32 %fB0, [%rdBPtr0];
    mul.wide.u32 %rdSB0, %rIdxB0, 4;
    add.s64      %rdSBPtr0, %rd_sB, %rdSB0;
    st.shared.f32 [%rdSBPtr0], %fB0;
    // idx1
    add.u32 %rIdxB1, %rTidLin, 256;
    and.b32 %rRowB1, %rIdxB1, 31;
    shr.u32 %rColB1, %rIdxB1, 5;
    add.u32 %rKGlobB1, %rKB, %rRowB1;
    add.u32 %rJGlobB1, %rBlockCol, %rColB1;
    setp.lt.u32 %pB1_k, %rKGlobB1, %rN;
    setp.lt.u32 %pB1_j, %rJGlobB1, %rN;
    and.pred %pB1, %pB1_k, %pB1_j;
    mul.lo.u32   %rBO1, %rKGlobB1, %rN;
    add.u32      %rBO1, %rBO1, %rJGlobB1;
    mul.wide.u32 %rdBO1, %rBO1, 4;
    add.s64      %rdBPtr1, %rdB, %rdBO1;
    mov.f32 %fB1, 0f00000000;
    @%pB1 ld.global.f32 %fB1, [%rdBPtr1];
    mul.wide.u32 %rdSB1, %rIdxB1, 4;
    add.s64      %rdSBPtr1, %rd_sB, %rdSB1;
    st.shared.f32 [%rdSBPtr1], %fB1;
    // Synchronize to ensure tiles are in shared memory
    bar.sync 0;
    // Accumulate this K tile contribution if this output is valid upper-triangular
    and.pred %p_compute, %p_valid, %p_upper;
    @!%p_compute bra SKIP_ACCUM;
    // Compute start and end k for this tile: [max(i,KB), min(j, KB+KTILE-1, N-1)]
    mov.u32 %rStart, %ri;
    setp.lt.u32 %p_lt0, %rStart, %rKB;
    @%p_lt0 mov.u32 %rStart, %rKB;              // rStart = max(ri, KB)
    mov.u32 %rEnd, %rj;
    setp.gt.u32 %p_gt0, %rEnd, %rNm1;
    @%p_gt0 mov.u32 %rEnd, %rNm1;               // rEnd = min(rj, N-1)
    add.u32 %rKBEnd, %rKB, 31;
    setp.gt.u32 %p_gt1, %rEnd, %rKBEnd;
    @%p_gt1 mov.u32 %rEnd, %rKBEnd;             // rEnd = min(rEnd, KB+31)
    // If rStart > rEnd, nothing to do in this tile
    setp.gt.u32 %p_empty, %rStart, %rEnd;
    @%p_empty bra AFTER_ACCUM;
    sub.u32 %rLocalStart, %rStart, %rKB;
    sub.u32 %rLocalEnd,   %rEnd,   %rKB;
    mov.u32 %rT, %rLocalStart;
ACCUM_LOOP:
    setp.gt.u32 %p_tdone, %rT, %rLocalEnd;
    @%p_tdone bra AFTER_ACCUM;
    // Load A_smem[ t*16 + row_local ]
    shl.b32 %rOffAIdx, %rT, 4;            // t * 16
    add.u32 %rOffAIdx, %rOffAIdx, %rTy;   // + row
    mul.wide.u32 %rdOffA, %rOffAIdx, 4;
    add.s64 %rdPtrA, %rd_sA, %rdOffA;
    ld.shared.f32 %fAt, [%rdPtrA];
    // Load B_smem[ col_local*32 + t ]
    shl.b32 %rOffBIdx, %rTx, 5;           // col * 32
    add.u32 %rOffBIdx, %rOffBIdx, %rT;    // + t
    mul.wide.u32 %rdOffB, %rOffBIdx, 4;
    add.s64 %rdPtrB, %rd_sB, %rdOffB;
    ld.shared.f32 %fBt, [%rdPtrB];
    // FMA
    fma.rn.f32 %fAcc, %fAt, %fBt, %fAcc;
    add.u32 %rT, %rT, 1;
    bra ACCUM_LOOP;
AFTER_ACCUM:
SKIP_ACCUM:
    // Synchronize before loading next tiles
    bar.sync 0;
    // Next K tile
    add.u32 %rKB, %rKB, 32;
    bra K_LOOP;
K_DONE:
    // Store result if within bounds
    @!%p_valid bra DONE;
    // Compute output value: 0 if lower-tri, fAcc otherwise
    mov.f32 %fOut, 0f00000000;
    @%p_upper mov.f32 %fOut, %fAcc;
    // C[i, j] = fOut
    mul.lo.u32   %rCbase, %ri, %rN;     // ri * N
    add.u32      %rCidx, %rCbase, %rj;  // i*N + j
    mul.wide.u32 %rdCoff, %rCidx, 4;
    add.s64      %rdCptr, %rdC, %rdCoff;
    st.global.f32 [%rdCptr], %fOut;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("ut_triu_matmul_f32")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A, B):
        assert A.device.type == "cuda" and B.device.type == "cuda", "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "Only float32 is supported"
        assert A.ndim == 2 and B.ndim == 2 and A.shape == B.shape and A.shape[0] == A.shape[1], "Inputs must be square matrices"
        N = A.shape[0]
        C = torch.empty_like(A)
        module = _get_ptx_module()

        block_x = 16
        block_y = 16
        grid_x = (N + block_x - 1) // block_x
        grid_y = (N + block_y - 1) // block_y

        module.launch(
            "ut_triu_matmul_f32",
            grid=(grid_x, grid_y, 1),
            block=(block_x, block_y, 1),
            arguments=[A, B, C, u32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

