.version 8.0
.target sm_89
.address_size 64
.visible .entry ut_triu_matmul_f32(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 N_param
)
{
    .reg .pred   %p<8>;
    .reg .b32    %r<48>;
    .reg .b64    %rd<32>;
    .reg .f32    %f<16>;
    .reg .b32    %rN, %rBx, %rBy, %rTx, %rTy, %rBDx, %rBDy, %ri, %rj, %rk, %rRowA;
    // Load parameters
    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %rN,  [N_param];
    // Compute thread coordinates (j = x, i = y)
    mov.u32 %rBx, %ctaid.x;
    mov.u32 %rBy, %ctaid.y;
    mov.u32 %rTx, %tid.x;
    mov.u32 %rTy, %tid.y;
    mov.u32 %rBDx, %ntid.x;
    mov.u32 %rBDy, %ntid.y;
    mul.lo.u32 %r0, %rBx, %rBDx;    // r0 = blockIdx.x * blockDim.x
    add.u32    %rj, %r0,  %rTx;     // j index
    mul.lo.u32 %r1, %rBy, %rBDy;    // r1 = blockIdx.y * blockDim.y
    add.u32    %ri, %r1,  %rTy;     // i index
    // Bounds check: if i >= N or j >= N, return
    setp.ge.u32 %p0, %ri, %rN;
    setp.ge.u32 %p1, %rj, %rN;
    or.pred     %p2, %p0, %p1;
    @%p2 bra DONE;
    // If i > j, write zero and return
    setp.gt.u32 %p3, %ri, %rj;
    @!%p3 bra COMPUTE; // if not (i>j), go compute
    // STORE ZERO PATH
    // idxC = i*N + j
    mul.lo.u32   %r2, %ri, %rN;
    add.u32      %r3, %r2, %rj;
    mul.wide.u32 %rd10, %r3, 4;
    add.s64      %rd11, %rd3, %rd10;
    mov.f32      %f0, 0f00000000;
    st.global.f32 [%rd11], %f0;
    bra DONE;
COMPUTE:
    // sum over k from i to j (inclusive) with A vectorized loads (v2) and unrolling by 2
    mov.f32 %f1, 0f00000000;   // accumulator
    mov.u32 %rk, %ri;          // k = i
    // Precompute row base for A: i * N
    mul.lo.u32 %rRowA, %ri, %rN;
ALIGN_PRE:
    // Align A address to 8B boundary for ld.global.v2.f32: ensure ((i*N + k) & 1) == 0
    setp.gt.u32 %p4, %rk, %rj;
    @%p4 bra END_LOOP;
    xor.b32 %r20, %rk, %rRowA;     // parity differs if LSB is 1
    and.b32 %r21, %r20, 1;
    setp.eq.u32 %p5, %r21, 0;
    @%p5 bra AFTER_ALIGN;
    // Scalar step to reach alignment
    // Load A[i, k]
    add.u32      %r5, %rRowA, %rk;     // i*N + k
    mul.wide.u32 %rd4, %r5, 4;         // byte offset
    add.s64      %rd5, %rd1, %rd4;     // A ptr + offset
    ld.global.f32 %f2, [%rd5];
    // Load B[k, j]
    mul.lo.u32   %r6, %rk, %rN;        // k * N
    add.u32      %r7, %r6, %rj;        // k*N + j
    mul.wide.u32 %rd6, %r7, 4;
    add.s64      %rd7, %rd2, %rd6;     // B ptr + offset
    ld.global.f32 %f3, [%rd7];
    // Accumulate
    fma.rn.f32 %f1, %f2, %f3, %f1;
    // k++ and loop
    add.u32 %rk, %rk, 1;
    bra ALIGN_PRE;
AFTER_ALIGN:
VEC_LOOP:
    // Guard: if rk > rj, end compute to store result
    setp.gt.u32 %p4, %rk, %rj;
    @%p4 bra END_LOOP;
    // Vectorized loop: process two k's per iteration when (rk + 1) <= j
    add.u32 %r22, %rk, 1;             // r22 = rk + 1
    setp.gt.u32 %p6, %r22, %rj;       // if (rk + 1) > j
    @%p6 bra SCALAR_TAIL;
    // Load A[i, rk : rk+1] as v2
    add.u32      %r5, %rRowA, %rk;    // i*N + k
    mul.wide.u32 %rd4, %r5, 4;
    add.s64      %rd5, %rd1, %rd4;
    ld.global.v2.f32 {%f2, %f3}, [%rd5];
    // Load B[rk, j]
    mul.lo.u32   %r6, %rk, %rN;       // rk * N
    add.u32      %r7, %r6, %rj;       // rk*N + j
    mul.wide.u32 %rd6, %r7, 4;
    add.s64      %rd7, %rd2, %rd6;
    ld.global.f32 %f4, [%rd7];        // B[rk, j]
    // Load B[rk+1, j]
    add.u32      %r6, %r6, %rN;       // (rk+1) * N
    add.u32      %r7, %r6, %rj;       // (rk+1)*N + j
    mul.wide.u32 %rd8, %r7, 4;
    add.s64      %rd9, %rd2, %rd8;
    ld.global.f32 %f5, [%rd9];        // B[rk+1, j]
    // Accumulate two FMAs
    fma.rn.f32 %f1, %f2, %f4, %f1;
    fma.rn.f32 %f1, %f3, %f5, %f1;
    // k += 2
    add.u32 %rk, %rk, 2;
    bra VEC_LOOP;
SCALAR_TAIL:
    // Process remaining k's (at most one remains due to vectorization)
TAIL_LOOP:
    setp.gt.u32 %p7, %rk, %rj;
    @%p7 bra END_LOOP;
    // Load A[i, k]
    add.u32      %r5, %rRowA, %rk;    // i*N + k
    mul.wide.u32 %rd4, %r5, 4;
    add.s64      %rd5, %rd1, %rd4;
    ld.global.f32 %f2, [%rd5];
    // Load B[k, j]
    mul.lo.u32   %r6, %rk, %rN;       // k * N
    add.u32      %r7, %r6, %rj;       // k*N + j
    mul.wide.u32 %rd6, %r7, 4;
    add.s64      %rd7, %rd2, %rd6;
    ld.global.f32 %f3, [%rd7];
    // Accumulate
    fma.rn.f32 %f1, %f2, %f3, %f1;
    // k++
    add.u32 %rk, %rk, 1;
    bra TAIL_LOOP;
END_LOOP:
    // Store C[i, j]
    mul.lo.u32   %r8, %ri, %rN;     // ri * N
    add.u32      %r9, %r8, %rj;     // i*N + j
    mul.wide.u32 %rd12, %r9, 4;     // byte offset
    add.s64      %rd13, %rd3, %rd12;  // C ptr + offset
    st.global.f32 [%rd13], %f1;
DONE:
    ret;
}
"""

